-- 00_PRECHECK_CLOUD.sql — READ-ONLY 선판정 [E20260930-DMF0082FXZERO] · 빌드 2026-09-30 21:43 · 원천 사내 ZIOUI1
--  ⚠ QA · DEV 두 DB 모두 · JUDGE 가 '적용'/'SKIP' 이 아니면 11 을 적용하지 말고 12 수동 반영(README §4)
SET PAGESIZE 200 LINESIZE 250
COLUMN JUDGE FORMAT A95
PROMPT [E0] 접속 DB
SELECT USER USR, SYS_CONTEXT('USERENV','DB_NAME') DB_NAME, SYS_CONTEXT('USERENV','SERVER_HOST') HOST FROM DUAL;
PROMPT [H0] PKG_DMF0082 SPEC/BODY 상태 (SPEC 은 변경 없음 — 둘 다 VALID 여야 정상)
SELECT OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL FROM USER_OBJECTS WHERE OBJECT_NAME='PKG_DMF0082' ORDER BY 1;
PROMPT [H] PKG_DMF0082 BODY 지문 — 전 16375/843903 (= DMF0082_CUSTEXCEL_CLOUD_20260930 적용본) · 후 16390/847373
SELECT LN || '/' || CH BODY_FP, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%--[E20260930-DMF0082FXZERO] 원문:%') MARK_LINES, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TRIM(BOTH ' ' FROM TRIM(BOTH CHR(9) FROM RTRIM(TEXT, CHR(10)||CHR(13)))) = 'JOIN GT_F020_EXCH B') ACTIVE_INNER_JOIN, (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TRIM(BOTH ' ' FROM TRIM(BOTH CHR(9) FROM RTRIM(TEXT, CHR(10)||CHR(13)))) = q'[WHERE M.MEASURE IN ('KRW', 'USD', 'LOC') AND M.QTY_PRICE <> 0)]') ACTIVE_OLD_PH2,
       CASE WHEN LN = 16390 AND CH = 847373 THEN 'SKIP — 이미 적용됨'
            WHEN LN = 16375 AND CH = 843903 THEN '적용 — 05 → 11 → 13 → 90'
            WHEN (SELECT COUNT(*) FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND TEXT LIKE '%--[E20260930-DMF0082FXZERO] 원문:%') = 10 THEN 'SKIP? — 마커 10 전부 존재하나 지문 상이(타 변경 병존). 90 으로 확인'
            ELSE '⚠ 11 적용 금지 — 지문 상이(CUSTEXCEL 누적본 미적용 또는 타 작업자 변경). 12 를 수동 반영 (README §4)' END JUDGE
  FROM (SELECT COUNT(*) LN, SUM(LENGTH(RTRIM(TEXT, CHR(10)||CHR(13)))) CH FROM USER_SOURCE WHERE NAME='PKG_DMF0082' AND TYPE='PACKAGE BODY' AND LINE > 1);
PROMPT [H2] 관련 GTT 존재 (저장: GT_PRDM1_T_MAIN · GT_PRDM1_TEMP_EXCH / Excel: GT_F020_UPLOAD_MASTER_FINAL · GT_F020_EXCH)
SELECT TABLE_NAME, TEMPORARY, DURATION FROM USER_TABLES WHERE TABLE_NAME IN ('GT_PRDM1_T_MAIN','GT_PRDM1_TEMP_EXCH','GT_F020_UPLOAD_MASTER_FINAL','GT_F020_EXCH') ORDER BY 1;
